<script setup lang="ts">
import {ref,computed,watch} from 'vue';import {layerDisplayVisible,setLayerDisplayVisible} from './networkLayerDisplay';import type {NetworkSegment,State} from './model';import {request} from './model';import {networkPath,canParentNetwork,networkSubtree} from './networkTree';import {networkRoomLabel} from './networkScope';import {useEditorDraft,useEditorBoundary} from './editorGuard';
const props=defineProps<{state:State;network:NetworkSegment;busy?:boolean}>();const emit=defineEmits<{saved:[state:State];busy:[value:boolean];preview:[network:NetworkSegment|undefined];members:[id:string];create:[parentId:string];edit:[network:NetworkSegment];layers:[id:string];remove:[network:NetworkSegment];select:[id:string]}>();
const root=ref<HTMLElement>(),name=ref(props.network.name),parent=ref(props.network.parentId||''),room=ref(props.network.roomScope==='project'?'__project':props.network.siteId||''),saving=ref(false),error=ref(''),revision=ref(props.state.revision);
const draft=useEditorDraft(()=>({name:name.value,parent:parent.value,room:room.value}),()=>saving.value);useEditorBoundary(root,()=>saving.value);
const changed=computed(()=>name.value!==props.network.name||parent.value!==(props.network.parentId||'')||room.value!==(props.network.roomScope==='project'?'__project':props.network.siteId||''));
const descendants=computed(()=>networkSubtree(props.state.networks,props.network.id).length-1);
watch([name,parent,room],()=>emit('preview',changed.value?{...props.network,name:name.value,parentId:parent.value,position:parent.value!==(props.network.parentId||'')?undefined:props.network.position,siteId:room.value==='__project'?'':room.value,roomScope:room.value==='__project'?'project':''}:undefined));
async function save(){if(saving.value||props.busy)return;saving.value=true;emit('busy',true);error.value='';try{const next=await request<State>('/networks/'+props.network.id,'PUT',{revision:revision.value,network:{...props.network,name:name.value.trim(),parentId:parent.value,position:parent.value!==(props.network.parentId||'')?undefined:props.network.position,siteId:room.value==='__project'?'':room.value,roomScope:room.value==='__project'?'project':''}});revision.value=next.revision;draft.accept();emit('preview',undefined);emit('saved',next)}catch(e){error.value=(e as Error).message}finally{saving.value=false;emit('busy',false)}}
</script>
<template><section ref="root" class="network-object-details" aria-label="网络详情"><p class="muted small">{{networkRoomLabel(state,network)}} · {{network.deviceIds.length}} 台直属设备 · {{descendants}} 个内部网络</p><div class="inspector-actions"><button class="primary" :disabled="busy" @click="emit('members',network.id)">添加设备</button><button class="secondary" :disabled="busy" @click="emit('create',network.id)">在此新建网络</button></div><section class="network-layer-controls" aria-label="分层显示"><label class="checkbox-label"><input type="checkbox" :checked="layerDisplayVisible(network)" aria-label="显示层名称与分隔线" @change="setLayerDisplayVisible(network.id,($event.target as HTMLInputElement).checked)"/>显示层名称与分隔线</label><button class="secondary" :disabled="busy" @click="emit('layers',network.id)">设置排列层</button></section><form @submit.prevent="save" @keydown="($event.ctrlKey||$event.metaKey)&&$event.key.toLowerCase()==='s'&&($event.preventDefault(),!saving&&($event.currentTarget as HTMLFormElement).requestSubmit())"><fieldset class="editor-fieldset" :disabled="busy||saving"><p v-if="error" class="error-banner" role="alert">{{error}}</p><label>网络名称<input v-model="name" name="networkName" required maxlength="80" autocomplete="off"/></label><label>所属机房<select v-model="room" aria-label="选中网络所属机房"><option value="">待指定机房（保留旧数据）</option><option v-for="r in state.sites.filter(r=>r.projectId===network.projectId)" :key="r.id" :value="r.id">{{r.name}}</option><option value="__project">跨机房（项目范围）</option></select></label><label>放置位置<select v-model="parent" aria-label="选中网络放置位置"><option value="">机房最外层</option><option v-for="n in state.networks.filter(n=>n.projectId===network.projectId&&n.id!==network.id&&canParentNetwork(state.networks,network.id,n.id))" :key="n.id" :value="n.id">{{networkPath(state.networks,n.id).map(p=>p.name).join(' / ')}} 内部</option></select></label><p v-if="changed" class="field-note" role="status">虚线框预览，点击应用后保存。设备、内部网络与真实连接保留。</p><button class="secondary full" :disabled="!changed||saving">{{saving?'正在保存…':'应用名称与放置位置'}}</button></fieldset></form><div class="inspector-actions"><button class="secondary" :disabled="busy" @click="emit('edit',network)">高级资料</button><button class="text-button danger-text" :disabled="busy" @click="emit('remove',network)">删除网络</button></div><p class="field-note">拖动标题只移动图上位置；更换上级在这里应用，不改变物理机位。</p><div class="inspector-network-list"><button v-for="n in state.networks.filter(n=>n.parentId===network.id)" :key="n.id" class="text-button" :disabled="busy" @click="emit('select',n.id)">定位 {{n.name}}</button></div></section></template>
